def configure_gsl_stats_mean(gsl):
    gsl.gsl_stats_mean.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t, ctypes.c_size_t]
    gsl.gsl_stats_mean.restype = ctypes.c_double


def compute_mean(data, stride, size):
    if not data:
        raise GSLException("Data array cannot be empty")
    if stride <= 0:
        raise GSLException("Stride must be positive")
    if size <= 0:
        raise GSLException("Size must be positive")

    try:
        gsl = load_gsl_libraries()
        configure_gsl_stats_mean(gsl)

        data_array = (ctypes.c_double * len(data))(*data)
        result = gsl.gsl_stats_mean(data_array, ctypes.c_size_t(stride), ctypes.c_size_t(size))
