import numpy as np

class GSLMatrix:
    def __init__(self, data):
        self.data = data
        self.size = len(data)
        self.n = self.size
        self.m = self.size
        self.storage = (ctypes.c_double * (self.n * self.m))()
        for i in range(self.n):
            for j in range(self.m):
                self.storage[i * self.m + j] = data[i][j]

    @property
    def pointer(self):
        return ctypes.pointer(self.storage)

class GSLPermutation:
    def __init__(self, size):
        self.size = size
        self.perm = (ctypes.c_int * size)()

    @property
    def pointer(self):
        return ctypes.pointer(self.perm)

