gsl.gsl_linalg_LU_decomp.restype = ctypes.c_int


def lu_decomposition(matrix):
    n = len(matrix)
    mat = GSLMatrix(matrix)
    perm = GSLPermutation(n)
    signum = ctypes.c_int(0)

    status = gsl.gsl_linalg_LU_decomp(mat.pointer, n, perm.pointer, ctypes.byref(signum))

    if status != 0:
        raise ValueError(f"LU decomposition failed with status code {status}")

    result = []
    for i in range(n):
        row = []
        for j in range(n):
            row.append(mat.storage[i * n + j])
        result.append(row)

    return result, list(perm.perm), int(signum.value)

