def compute_gastwirth_mean(sorted_data, stride, n):
    if n == 0:
        return float('nan')

    gsl = load_gsl_libraries()

    # Define function signature for gsl_stats_gastwirth_from_sorted_data
    gsl.gsl_stats_gastwirth_from_sorted_data.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.c_int]
    gsl.gsl_stats_gastwirth_from_sorted_data.restype = ctypes.c_double

    # Convert input list to ctypes array
    data = (ctypes.c_double * len(sorted_data))(*sorted_data)

    # Call GSL function
    result = gsl.gsl_stats_gastwirth_from_sorted_data(data, stride, n)

    return float(result)

