    class gsl_function(ctypes.Structure):
        _fields_ = [
            ('f', ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)),
            ('x', ctypes.c_double),
            ('params', ctypes.c_void_p)
        ]

    gsl.gsl_integration_qk21.argtypes = [
        ctypes.POINTER(gsl_function),
        ctypes.c_double,
        ctypes.c_double,
        ctypes.POINTER(ctypes.c_double),
        ctypes.POINTER(ctypes.c_double),
        ctypes.POINTER(ctypes.c_double),
        ctypes.POINTER(ctypes.c_double)
    ]

    gsl.gsl_integration_qk21.restype = ctypes.c_int

    func = GSLFunction(function)
    gsl_func = gsl_function()
    gsl_func.f = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(lambda x: func.f1(x))
    gsl_func.x = ctypes.c_double(0.0)
    gsl_func.params = ctypes.c_void_p(0)

    res = ctypes.c_double(0.0)
    resabs = ctypes.c_double(0.0)
    resasc = ctypes.c_double(0.0)
    err = ctypes.c_double(0.0)

    gsl.gsl_integration_qk21(ctypes.pointer(gsl_func), a, b, ctypes.pointer(res), ctypes.pointer(resabs), ctypes.pointer(resasc), ctypes.pointer(err))

    return float(res), float(resabs), float(resasc), float(err)

