import ctypes
import numpy as np
import numpy.linalg as la
import sys

class GSLMatrix:
    def __init__(self, size):
        self.size = size
        self.data = np.zeros((size, size), dtype=np.float64)
        self._pointer = self.data.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

    def __getitem__(self, key):
        return self.data[key]

    def __setitem__(self, key, value):
        self.data[key] = value

    def get_pointer(self):
        return self._pointer

    def get_size(self):
        return self.size


def matrix_to_gsl(matrix):
    size = len(matrix)
    gsl_matrix = GSLMatrix(size)
    for i in range(size):
        for j in range(size):
            gsl_matrix[i, j] = matrix[i][j]
    return gsl_matrix


def gsl_matrix_to_numpy(gsl_matrix):
    numpy_matrix = np.zeros((gsl_matrix.get_size(), gsl_matrix.get_size()), dtype=np.float64)
    numpy_matrix[:] = gsl_matrix.data
    return numpy_matrix


def compute_matrix_exponential(matrix, mode):
    try:
        if not isinstance(matrix, list) or not all(isinstance(row, list) for row in matrix):
            raise ValueError("Input matrix must be a 2D list of floats.")
        size = len(matrix)
        if any(len(row) != size for row in matrix):
            raise ValueError("All rows in the matrix must have the same length.")
        if not isinstance(mode, int):
            raise ValueError("Mode must be an integer.")

        gsl_matrix = matrix_to_gsl(matrix)
        gsl_matrix_pointer = gsl_matrix.get_pointer()
        gsl_matrix_size = gsl_matrix.get_size()

        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        gsl.gsl_linalg_exponential_ss.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.c_int]
        gsl.gsl_linalg_exponential_ss.restype = ctypes.c_int

        result = np.zeros((size, size), dtype=np.float64)
        result_ptr = result.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

        status = gsl.gsl_linalg_exponential_ss(gsl_matrix_pointer, gsl_matrix_size, result_ptr, mode, 0)

        if status != 0:
            raise RuntimeError(f"GSL function returned error code {status}")

        return gsl_matrix_to_numpy(gsl_matrix)
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    test_matrix = [[1.0, 2.0], [3.0, 4.0]]
    mode = 0
    result = compute_matrix_exponential(test_matrix, mode)
    print("Matrix Exponential:")
    for row in result:
        print(row)

