class GSLMatrix:
    def __init__(self, data, size):
        self.size = size
        self.data = (ctypes.c_double * (size[0] * size[1]))()
        for i in range(size[0]):
            for j in range(size[1]):
                self.data[i * size[1] + j] = data[i][j]

    def __getitem__(self, key):
        return self.data[key[0] * self.size[1] + key[1]]

    def __setitem__(self, key, value):
        self.data[key[0] * self.size[1] + key[1]] = value

    def to_numpy(self):
        return np.ctypeslib.as_array(self.data, shape=(self.size[0], self.size[1]))


def matrix_to_gsl(matrix):
    size = (len(matrix), len(matrix[0]))
    return GSLMatrix(matrix, size)

def gsl_matrix_to_numpy(gsl_matrix):
    return np.ctypeslib.as_array(gsl_matrix.data, shape=(gsl_matrix.size[0], gsl_matrix.size[1]))

def compute_matrix_exponential(matrix, mode):
    if not isinstance(matrix, list):
        raise ValueError("Input matrix must be a list of lists")
    n = len(matrix)
    for row in matrix:
        if len(row) != n:
            raise ValueError(f"Matrix dimensions are inconsistent: {n}x{n} expected")

    gsl_cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

