    gsl.gsl_linalg_exponential_ss.restype = None

    gsl_matrix = matrix_to_gsl(matrix)
    result = GSLMatrix([0.0]*n*n, (n, n))

    gsl.gsl_linalg_exponential_ss(result.data, n, mode, gsl_matrix.data)

    return gsl_matrix_to_numpy(result)

if __name__ == "__main__":
