import sys

class GSLMatrix:
    def __init__(self, data, size):
        self.size = size
        self.data = (ctypes.c_double * (size[0] * size[1]))()
        for i in range(size[0]):
            for j in range(size[1]):
                self.data[i * size[1] + j] = data[i][j]

    def to_c_array(self):
        return self.data

    @classmethod
def matrix_to_gsl(matrix):
    rows, cols = len(matrix), len(matrix[0])
    if not all(len(row) == cols for row in matrix):
        raise ValueError("Matrix is not rectangular")
    if rows != cols:
        raise ValueError("Matrix must be square")
    return GSLMatrix(matrix, (rows, cols))

def gsl_matrix_to_numpy(gsl_matrix):
    data = (ctypes.c_double * (gsl_matrix.size[0] * gsl_matrix.size[1]))()
    for i in range(gsl_matrix.size[0]):
