import ctypes
import numpy as np
import sys

class GSLFilterImpulseWorkspace:
    def __init__(self, size):
        self.size = size
        self.workspace = ctypes.c_void_p()
        self._init_workspace()

    def _init_workspace(self):
        libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        gsl.gsl_filter_impulse_workspace_alloc.argtypes = [ctypes.c_int]
        gsl.gsl_filter_impulse_workspace_alloc.restype = ctypes.c_void_p
        self.workspace = gsl.gsl_filter_impulse_workspace_alloc(self.size)

    def apply_filter(self, input_vector, output_vector):
        gsl.gsl_filter_impulse.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
        gsl.gsl_filter_impulse.restype = ctypes.c_int
        return gsl.gsl_filter_impulse(self.workspace, self.size, 1, input_vector, output_vector)


class GSLVector:
    def __init__(self, size):
        self.size = size
        self.data = (ctypes.c_double * size)()

    def set_data(self, data):
        for i in range(self.size):
            self.data[i] = data[i]

    def get_data(self):
        return np.array([self.data[i] for i in range(self.size)], dtype=np.float64)


class GSLVectorInt:
    def __init__(self, size):
        self.size = size
        self.data = (ctypes.c_int * size)()

    def set_data(self, data):
        for i in range(self.size):
            self.data[i] = data[i]

    def get_data(self):
        return np.array([self.data[i] for i in range(self.size)], dtype=np.int32)


def generate_signal(N):
    t = np.linspace(0, 2 * np.pi, N)
    signal = np.sin(t)
    noise = np.random.normal(0, 0.1, N)
    outliers = np.random.choice([0, 1], N, p=[0.99, 0.01])
    outliers *= np.random.normal(0, 10, N)
    return signal + noise + outliers


def main(N, K, t):
    signal = generate_signal(N)
    workspace = GSLFilterImpulseWorkspace(K)
    input_vec = GSLVector(N)
    input_vec.set_data(signal)
    output_vec = GSLVector(N)
    status = workspace.apply_filter(input_vec.data, output_vec.data)

    median = np.median(signal)
    sigma = np.std(signal)
    lower_bound = median - t * sigma
    upper_bound = median + t * sigma

    outlier_status = GSLVectorInt(N)
    for i in range(N):
        if signal[i] < lower_bound or signal[i] > upper_bound:
            outlier_status.data[i] = 1
        else:
            outlier_status.data[i] = 0

    print("Filtered Signal:", output_vec.get_data())
    print("Median:", median)
    print("Sigma:", sigma)
    print("Lower Bound:", lower_bound)
    print("Upper Bound:", upper_bound)
    print("Outlier Status:", outlier_status.get_data())

if __name__ == "__main__":
    N = int(sys.argv[1])
    K = int(sys.argv[2])
    t = float(sys.argv[3])
    main(N, K, t)

