        """Check if the matrix is positive definite."""
        lib = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        lib.gsl_linalg_cholesky_decomp.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int]
