        result = lib.gsl_linalg_cholesky_decomp(self.data, self.n)
        return result == 0

    def cholesky_decomp(self):
        """Perform Cholesky decomposition on a positive definite matrix."""
        lib = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        lib.gsl_linalg_choles,ky_decomp.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int]
