        if not self.is_positive_definite():
            raise ValueError("Matrix is not positive definite.")

        result = lib.gsl_linalg_cholesky_decomp(self.data, self.n)
        if result != 0:
            raise RuntimeError("Cholesky decomposition failed.")

        lower_triangle = np.zeros((self.n, self.n))
        for i in range(self.n):
            for j in range(i + 1):
                lower_triangle[i][j] = self.data[i * self.n + j]
        return lower_triangle.tolist()

